    },
    {
      "card_ids": ["C04"],
      "claim": "Brepocitinib absolute oral bioavailability was estimated at 75% in a human mass balance study, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brigatinib oral bioavailability was approximately 46% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple human absolute bioavailability studies in physicochemically relevant molecules show F values well above 20% (GSK1322322 57-77%, imatinib 98%, brepocitinib 75%, brigatinib 46%), overriding the uncertain physicochemical prior; therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "No retrieved analogue with F < 20% to support a low prediction.",
    "One retrieved record is a predicted human PK value rather than a measured absolute bioavailability.",
    "Permeability, efflux, and metabolic stability data for the query are not directly available."
  ],
